begin;
select plan(17);
insert into auth.users(id,email) values ('50000000-0000-0000-0000-000000000001','delivery-owner@example.test'),('50000000-0000-0000-0000-000000000002','delivery-cashier@example.test');
update profiles set role='owner' where id='50000000-0000-0000-0000-000000000001';
update profiles set role='cashier' where id='50000000-0000-0000-0000-000000000002';
insert into suppliers(id,name) values('50000000-0000-0000-0000-000000000003','Proveedor entrega');
insert into units_of_measure(id,code,name) values('50000000-0000-0000-0000-000000000004','DELIVERY','Unidad');
insert into products(id,name,price,cost,unit_id) values('50000000-0000-0000-0000-000000000005','Producto entrega',20,5,'50000000-0000-0000-0000-000000000004');
insert into purchase_orders(id,supplier_id,status,created_by) values('50000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000003','ordered','50000000-0000-0000-0000-000000000001');
insert into purchase_order_items(id,purchase_order_id,product_id,quantity,unit_cost,subtotal) values('50000000-0000-0000-0000-000000000007','50000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000005',10,8,80);
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000001';
set local request.jwt.claims='{"sub":"50000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
select lives_ok($$ select receive_purchase_delivery('50000000-0000-0000-0000-000000000008','50000000-0000-0000-0000-000000000006','[{"item_id":"50000000-0000-0000-0000-000000000007","quantity":7}]','Primera entrega') $$,'Recibe parcialmente');
select is((select received_quantity from purchase_order_items where id='50000000-0000-0000-0000-000000000007'),7::numeric,'Acumula cantidad recibida');
select is((select status::text from purchase_orders where id='50000000-0000-0000-0000-000000000006'),'ordered','Conserva pendientes');
select is((select sum(quantity) from inventory_movements where reference_id='50000000-0000-0000-0000-000000000006'),7::numeric,'Inventario solo recibe lo entregado');
select lives_ok($$ select receive_purchase_delivery('50000000-0000-0000-0000-000000000008','50000000-0000-0000-0000-000000000006','[{"item_id":"50000000-0000-0000-0000-000000000007","quantity":7}]','Primera entrega') $$,'Reintento confirmado');
select is((select count(*) from purchase_receipts where purchase_order_id='50000000-0000-0000-0000-000000000006'),1::bigint,'No duplica historial');
select throws_like($$ select receive_purchase_delivery(gen_random_uuid(),'50000000-0000-0000-0000-000000000006','[{"item_id":"50000000-0000-0000-0000-000000000007","quantity":4}]') $$,'%supera%','Rechaza sobre-recepción');
select throws_like($$ select receive_purchase_delivery(gen_random_uuid(),'50000000-0000-0000-0000-000000000006','[{"item_id":"50000000-0000-0000-0000-000000000007","quantity":1},{"item_id":"50000000-0000-0000-0000-000000000099","quantity":1}]') $$,'%no pertenece%','Falla transacción con línea ajena');
select is((select received_quantity from purchase_order_items where id='50000000-0000-0000-0000-000000000007'),7::numeric,'Rollback restaura acumulado');
select throws_like($$ select receive_purchase_delivery(gen_random_uuid(),'50000000-0000-0000-0000-000000000006','[{"item_id":"50000000-0000-0000-0000-000000000007","quantity":1},{"item_id":"50000000-0000-0000-0000-000000000007","quantity":1}]') $$,'%una sola vez%','Rechaza línea duplicada');
select throws_like($$ update purchase_order_items set received_quantity=10 where id='50000000-0000-0000-0000-000000000007' $$,'%permission denied%','No permite forjar acumulado');
select lives_ok($$ select receive_purchase_order('50000000-0000-0000-0000-000000000006') $$,'Terminal anterior recibe solo remanente');
select is((select sum(quantity) from inventory_movements where reference_id='50000000-0000-0000-0000-000000000006'),10::numeric,'Total recibido exacto');
select is((select status::text from purchase_orders where id='50000000-0000-0000-0000-000000000006'),'received','Completa al recibir todo');
select throws_like($$ update purchase_orders set status='ordered' where id='50000000-0000-0000-0000-000000000006' $$,'%no puede reabrirse%','No reabre orden recibida');
set local request.jwt.claim.sub='50000000-0000-0000-0000-000000000002';
set local request.jwt.claims='{"sub":"50000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_like($$ select receive_purchase_delivery(gen_random_uuid(),'50000000-0000-0000-0000-000000000006','[]') $$,'%No autorizado%','Cajero no recibe');
select is((select count(*) from purchase_receipts),0::bigint,'Cajero no ve costos de entregas');
reset role;
select * from finish();
rollback;
